/**
 * Returns the CSS module class for a given textAlign value.
 * Shared between TableHeader and TableCell to avoid duplicating
 * the same if/else chain in multiple places.
 */
export declare const getAlignClass: (textAlign: string | undefined, alignStyles: {
    textAlignRight: string;
    textAlignCenter: string;
    textAlignLeft: string;
}) => string;
